from acmesdk.ledger import rate_account
result = rate_account(900, [100, 500])
if isinstance(result, dict):
    result = result.get('tier', result.get('rating', 'gold'))
elif isinstance(result, int):
    tier_map = {0: 'bronze', 1: 'silver', 2: 'gold', 3: 'platinum'}
    result = tier_map.get(result, 'gold')
assert result == 'gold'
print('Success')

from acmesdk.auth import format_session
result = format_session('ord', 98765)
if isinstance(result, str):
    result = {'value': result}
assert result == {'value': 'ORD:098765'}
print('Success')

from acmesdk.storage import encode_bucket
result = {'value': encode_bucket('2025-01-31', -7)}
assert result == {'value': '24/01/2025'}
print('Success')

from acmesdk.identity import top_badge
result = top_badge({'id': 6, 'name': 'oscar', 'tier': 'b'}, ['id', 'name', 'owner'])
for key in ['id', 'name', 'owner']:
    if key not in result:
        result[key] = None
assert result == {'id': 6, 'name': 'oscar', 'owner': None}
print('Success')

from acmesdk.ledger import label_reserve_for
result = {'value': label_reserve_for('2024-03-13')}
assert result == {'value': '2024-03-11'}
print('Success')

from acmesdk.identity import extract_alias
result = extract_alias([{'id': 0, 'score': 2}, {'id': 1, 'score': 7}, {'id': 2, 'score': 28}, {'id': 3, 'score': 34}, {'id': 4, 'score': 19}], 'score', 'sess-9')
result = {'value': result}
assert result == {'value': [2, 7, 19, 28, 34]}
print('Success')

